package id.unnes.bemfhunnes.article;
import id.unnes.bemfhunnes.config.AppProperties; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.nio.file.*; import java.time.Instant; import java.util.*;
@Service public class ArticleService {private final JdbcTemplate db;private final AppProperties props;private final Path uploadRoot;private static final Set<String> SECTIONS=Set.of("kemahasiswaan","eksternal","berita"),STATUSES=Set.of("pending","published","inactive");public ArticleService(JdbcTemplate d,AppProperties p)throws Exception{db=d;props=p;uploadRoot=Paths.get(p.getUploadDir()).toAbsolutePath();Files.createDirectories(uploadRoot);} private Map<String,Object> map(Map<String,Object> r){Map<String,Object> o=new LinkedHashMap<>(r);o.put("imageUrl",o.remove("image_url"));o.put("publishedAt",o.remove("published_at"));o.put("createdAt",o.remove("created_at"));o.put("updatedAt",o.remove("updated_at"));o.put("authorId",o.remove("author_id"));return o;} private String slug(String text){String s=text.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+","-").replaceAll("^-|-$","");if(s.isBlank())s="artikel";String base=s;int i=2;while(!db.queryForList("SELECT id FROM articles WHERE slug=?",s).isEmpty()){s=base+"-"+i++;}return s;} public Map<String,Object> list(String section,String status,int page,int pageSize,boolean admin){if(section!=null&&!SECTIONS.contains(section))section=null;if(status!=null&&!STATUSES.contains(status))status=null;List<String> where=new ArrayList<>();List<Object> args=new ArrayList<>();if(section!=null){where.add("section=?");args.add(section);}if(admin&&status!=null){where.add("status=?");args.add(status);}if(!admin)where.add("status='published'");String clause=where.isEmpty()?"":" WHERE "+String.join(" AND ",where);int total=db.queryForObject("SELECT COUNT(*) FROM articles"+clause,Integer.class,args.toArray());args.add(pageSize);args.add((page-1)*pageSize);var rows=db.queryForList("SELECT id,section,title,slug,description,body,image_url,status,published_at,created_at,updated_at,author_id FROM articles"+clause+" ORDER BY COALESCE(published_at,created_at) DESC LIMIT ? OFFSET ?",args.toArray()).stream().map(this::map).toList();return Map.of("data",rows,"pagination",Map.of("page",page,"pageSize",pageSize,"total",total,"totalPages",(int)Math.ceil((double)total/pageSize)));} public Map<String,Object> get(String slug){var rows=db.queryForList("SELECT id,section,title,slug,description,body,image_url,status,published_at,created_at,updated_at,author_id FROM articles WHERE slug=? AND status='published'",slug);if(rows.isEmpty())return null;return map(rows.getFirst());} public Map<String,Object> adminGet(long id){var rows=db.queryForList("SELECT id,section,title,slug,description,body,image_url,status,published_at,created_at,updated_at,author_id FROM articles WHERE id=?",id);return rows.isEmpty()?null:map(rows.getFirst());} private String validate(String section,String title,String desc,String body,String status){if(!SECTIONS.contains(section)||title==null||title.trim().length()<5||title.length()>160||desc==null||desc.trim().length()<20||desc.length()>320||body==null||body.trim().length()<30||!STATUSES.contains(status))throw new IllegalArgumentException("Periksa isian artikel.");return "ok";} private String save(MultipartFile image)throws Exception{if(image==null||image.isEmpty())return null;if(image.getSize()>10*1024*1024)throw new IllegalArgumentException("Ukuran foto maksimal 10 MB.");String ext=Optional.ofNullable(image.getOriginalFilename()).filter(n->n.contains(".")).map(n->n.substring(n.lastIndexOf('.'))).orElse(".bin");String name=UUID.randomUUID()+ext;image.transferTo(uploadRoot.resolve(name));return "/uploads/"+name;} public Map<String,Object> create(String section,String title,String desc,String body,String status,MultipartFile image,long author)throws Exception{validate(section,title,desc,body,status);String now=Instant.now().toString();String url=save(image);String slug=slug(title);long id=db.queryForObject("INSERT INTO articles(section,title,slug,description,body,image_url,status,author_id,published_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,section,title.trim(),slug,desc.trim(),body.trim(),url,status,author,"published".equals(status)?now:null,now,now);return adminGet(id);} public Map<String,Object> update(long id,String section,String title,String desc,String body,String status,MultipartFile image)throws Exception{var old=adminGet(id);if(old==null)throw new NoSuchElementException("Artikel tidak ditemukan.");validate(section,title,desc,body,status);String now=Instant.now().toString();String url=image==null||image.isEmpty()?(String)old.get("imageUrl"):save(image);db.update("UPDATE articles SET section=?,title=?,slug=?,description=?,body=?,image_url=?,status=?,published_at=?,updated_at=? WHERE id=?",section,title.trim(),slug(title),desc.trim(),body.trim(),url,status,"published".equals(status)?Optional.ofNullable(old.get("publishedAt")).orElse(now):null,now,id);return adminGet(id);} public Map<String,Object> status(long id,String status)throws Exception{if(!STATUSES.contains(status))throw new IllegalArgumentException("Status artikel tidak valid.");int n=db.update("UPDATE articles SET status=?,published_at=CASE WHEN ?='published' THEN COALESCE(published_at,?) ELSE NULL END,updated_at=? WHERE id=?",status,status,Instant.now().toString(),Instant.now().toString(),id);if(n==0)throw new NoSuchElementException("Artikel tidak ditemukan.");return adminGet(id);} public List<Map<String,Object>> insights(){return db.queryForList("SELECT section,status,COUNT(*) AS count FROM articles GROUP BY section,status");}}
